{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PRESENT",
      "chunk_id": "text_7",
      "quote": "Two independent authors (A.B. and G.P.) completed reference screening and study selection using the following predefined inclusion criteria: (1) population : children, young people, or adults who have experienced a suspected hemorrhage or TBI following a traumatic incident; (2) intervention : administration of a systemic hemostatic agent, (e.g., rFVIIa, TXA, fibrinogen concentrate, prothrombin complex concentrate, or another anti-fibrinolytic agent); (3) comparison : no treatment, placebo, standard care (e.g., crystalloids, blood components), or any other hemostatic agent; and (iv) setting: systemic hemostatic treatment initiated in the prehospital setting. Only RCTs were considered eligible for inclusion; case reports, editorials, and letters were excluded from the search. When multiple publications for the same trial reported different outcomes or follow-up data, they were counted as a single publication.",
      "reason": "Specifies study characteristics including PICO components, eligible study designs (RCTs), settings (pre-hospital), and follow-up requirements."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No evidence found specifying eligibility criteria for report characteristics such as dissemination year, language, or publication status."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The review does not appear to exclude studies based on outcomes not measured or not reported; eligibility is based on study design and PICO criteria."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PRESENT",
      "chunk_id": "text_10",
      "quote": "Subgroup analyses were planned for (1) type of population (e.g., subjects with significant hemorrhage and subjects with TBI); (2) type of injury (e.g., blunt trauma, penetrating trauma); and (3) doses of systemic hemostatic agent when available.",
      "reason": "Specifies groups used in syntheses, linked to comparisons defined in review objectives (e.g., population types)."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "PRESENT",
      "chunk_id": "text_21",
      "quote": "Inclusion criteria were narrow, aiming to balance pros and cons. We considered eligible all RCTs that investigated several interventions delivered in any setting (civilian and military). Thus, although we were able to offer the highest level of evidence (RCTs with high certainty of evidence) achieving more consistency in the interpretation of findings, this approach limited the results as we did not find studies in military setting or studies involving fibrinogen concentrates, prothrombin complex concentrate, or other anti-fibrinolytic agents.",
      "reason": "Rationale provided for restricting study eligibility to RCTs to ensure high certainty of evidence."
    }
  ],
  "confidence": 90
}

